import * as React from 'react'

import Main from './Main'
import history from '../history'

export default function App () {
  const [, forceUpdate] = React.useReducer((value: number) => value + 1, 0)

  React.useEffect(() => {
    const unlisten = history.listen(() => forceUpdate())
    return unlisten
  }, [])

  return <Main />
}
